// ✅ Step 1: Show single record count + Confirm Delete button
function showResetConfirm(title, label, count, color, description, doReset) {
  const overlay     = document.getElementById('reset-progress-overlay');
  const titleEl     = document.getElementById('reset-progress-title');
  const countBox    = document.getElementById('reset-count-box');
  const barWrap     = document.getElementById('reset-bar-wrap');
  const doneArea    = document.getElementById('reset-done-area');
  const confirmArea = document.getElementById('reset-confirm-area');
  const confirmBtn  = document.getElementById('reset-confirm-btn');
  const cancelBtn   = document.getElementById('reset-cancel-btn');
  const infoEl      = document.getElementById('reset-info-single');
  const countNumEl  = document.getElementById('reset-info-count');
  const descEl      = document.getElementById('reset-info-desc');

  titleEl.textContent    = title;
  infoEl.textContent     = label;
  infoEl.style.color     = color;
  countNumEl.textContent = count + ' records';
  countNumEl.style.color = color;
  descEl.textContent     = description;

  countBox.style.display    = 'block';
  confirmArea.style.display = 'block';
  barWrap.style.display     = 'none';
  doneArea.style.display    = 'none';
  overlay.style.display     = 'flex';

  // Remove old listeners to avoid double-fire
  const newConfirmBtn = confirmBtn.cloneNode(true);
  const newCancelBtn  = cancelBtn.cloneNode(true);
  confirmBtn.parentNode.replaceChild(newConfirmBtn, confirmBtn);
  cancelBtn.parentNode.replaceChild(newCancelBtn, cancelBtn);

  newCancelBtn.addEventListener('click', () => {
    overlay.style.display = 'none';
  });

  newConfirmBtn.addEventListener('click', () => {
    confirmArea.style.display = 'none';
    countBox.style.display    = 'none';
    barWrap.style.display     = 'block';
    runResetProgress(doReset);
  });
}

// ✅ Step 2: Progress bar + execute delete
function runResetProgress(doReset) {
  const bar      = document.getElementById('reset-progress-bar');
  const statusEl = document.getElementById('reset-progress-status');
  const doneArea = document.getElementById('reset-done-area');

  bar.style.width = '0%';
  statusEl.textContent = 'Starting...';
  doneArea.style.display = 'none';

  const steps = [
    { pct: 25, msg: 'Loading records...', ms: 300 },
    { pct: 55, msg: 'Removing records...', ms: 300 },
    { pct: 80, msg: 'Cleaning storage...', ms: 300 },
  ];

  let i = 0;
  function runStep() {
    if (i < steps.length) {
      const s = steps[i++];
      setTimeout(() => { bar.style.width = s.pct + '%'; statusEl.textContent = s.msg; runStep(); }, s.ms);
    } else {
      setTimeout(() => { bar.style.width = '100%'; statusEl.textContent = 'Finalizing...'; doReset(); }, 300);
    }
  }
  runStep();
}

function finishResetProgress(msg) {
  const bar      = document.getElementById('reset-progress-bar');
  const statusEl = document.getElementById('reset-progress-status');
  const doneArea = document.getElementById('reset-done-area');
  const doneMsg  = document.getElementById('reset-done-msg');

  bar.style.width = '100%';
  statusEl.textContent = 'Complete!';
  doneMsg.textContent = msg;
  doneArea.style.display = 'block';
}



