function renderPlans(plans) {
  const grid = $(PomOpadNzdsV(_$AtdJFEou[182]));
  if (!plans || !plans.length) {
    grid.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:20px;
      color:var(--text3);font-size:12px">No plans available</div>`;
    return;
  }
  
  function getBadgeClass(badge) {
    if (!badge) return 'plan-badge';
    const b = badge.toLowerCase();
    if (b.includes('popular')) return 'plan-badge popular';
    if (b.includes('free'))    return 'plan-badge free';
    if (b.includes('best'))    return 'plan-badge best-value';
    if (b.includes('enterprise')) return 'plan-badge enterprise';
    return 'plan-badge';
  }
  grid.innerHTML = plans.map((p, i) => `
    <div class="plan-card" data-plan-idx="${i}" id="plan-card-${i}">
      ${p.badge ? `<div class="${getBadgeClass(p.badge)}">${p.badge}</div>` : ''}
      <div class="plan-name">${p.name || ''}</div>
      <div class="plan-credits-num">${(p.credits || 0).toLocaleString()}</div>
      <div class="plan-credits-lbl">CREDITS</div>
      <div class="plan-price">৳${p.price || 0}</div>
      <div class="plan-per">৳${p.per_credit || '?'}/credit</div>
      ${p.save ? `<div class="plan-save">${p.save}</div>` : ''}
    </div>`).join('');
}

