async function verifyToken(token, cachedPhone) {
  // v26 FIX: Never auto-disconnect due to network issues or unknown errors.
  // Only disconnect on explicit authentication errors (invalid/expired token).
  try {
    const r = await fetch(`${WA_SERVER}/me?token=${token}`, { signal: AbortSignal.timeout(8000) });
    const d = await r.json();
    if (d.ok) {
      waToken = token; waConnected = true;
      showWaConnected(d.phone || cachedPhone);
      showWaToken(token);
    } else if (d.error && (d.error.includes('auth') || d.error.includes('invalid') || d.error.includes('expired'))) {
      // Only disconnect on explicit auth token errors
      showWaDisconnected();
    } else {
      // Server issue, unknown error, or temporary problem — KEEP connected
      waToken = token; waConnected = true;
      showWaConnected(cachedPhone || '');
      showWaToken(token);
    }
  } catch(e) {
    // Network error / timeout — ALWAYS keep connected, never auto-disconnect
    waToken = token; waConnected = true;
    showWaConnected(cachedPhone || '');
    showWaToken(token);
  }
}

