let importedLeads = [];
let importParsedRows = [];
let importHeaders = [];
let importColMap = { name:'', phone:'', email:'', whatsapp:'', website:'', address:'', rating:'', category:'' };
let importStopIndex = 0;      // track where WA send was stopped for resume
let importSendMode = 'idle';  // 'idle' | 'sending' | 'stopped'
let importSendType = 'wa';    // 'wa' | 'email'

// ── Persist importedLeads to storage ──
function saveImportedLeadsToStorage() {
  chrome.storage.local.set({ importedLeads: importedLeads, importStopIndex: importStopIndex });
}

// ── Restore importedLeads from storage on popup open ──
function restoreImportedLeads() {
  chrome.storage.local.get([
    'importedLeads','importStopIndex',
    'importSendStatus','importSendProgress','importSendTotal',
    'importEmailSendStatus','importEmailSendProgress',
    'importBothSendStatus','importBothSendProgress'
  ], (d) => {
    if (d.importedLeads && d.importedLeads.length > 0) {
      importedLeads = d.importedLeads;
      importStopIndex = d.importStopIndex || 0;
      const status      = d.importSendStatus      || 'idle';
      const emailStatus = d.importEmailSendStatus || 'idle';
      const bothStatus  = d.importBothSendStatus  || 'idle';

      const sendSec  = document.getElementById('import-send-section');
      const statsSec = document.getElementById('import-stats-section');
      if (statsSec) statsSec.style.display = 'block';
      if (sendSec)  sendSec.style.display  = 'block';

      const withPhone = importedLeads.filter(l => l.phone && l.phone !== '—').length;
      const withEmail = importedLeads.filter(l => l.email && l.email !== '—').length;
      const stTotal = document.getElementById('import-stat-total');
      const stPhone = document.getElementById('import-stat-phone');
      const stEmail = document.getElementById('import-stat-email');
      if (stTotal) stTotal.textContent = importedLeads.length;
      if (stPhone) stPhone.textContent = withPhone;
      if (stEmail) stEmail.textContent = withEmail;

      // ── Restore WA send state ──
      if (status === 'running') {
        importSendMode = 'sending';
        importStopIndex = d.importSendProgress || 0;
        const sp = document.getElementById('import-send-progress');
        if (sp) sp.style.display = 'block';
        const logEl = document.getElementById('import-send-log');
        if (logEl) logEl.dataset.rendered = '0';
        startImportProgressPoll();
        importLogInfo('🔄 WA Background sending চলছে — reconnecting...');
      } else if (status === 'stopped' && importStopIndex > 0 && importStopIndex < importedLeads.length) {
        importSendMode = 'stopped';
        importLog('📌 WA: ' + importStopIndex + '/' + importedLeads.length + ' পাঠানো — Resume করুন');
      } else if (status === 'done') {
        importSendMode = 'idle'; importStopIndex = 0;
      } else {
        importSendMode = 'idle';
        if (importStopIndex > 0) { importSendMode = 'stopped'; }
      }
      updateWaSendBtn();

      // ── Restore Email send state ──
      if (emailStatus === 'running') {
        _emailSendMode = 'sending';
        _emailStopIndex = d.importEmailSendProgress || 0;
        const ep = document.getElementById('import-email-progress');
        if (ep) ep.style.display = 'block';
        const logEl2 = document.getElementById('import-email-log');
        if (logEl2) logEl2.dataset.rendered = '0';
        startEmailProgressPoll();
      } else if (emailStatus === 'stopped') {
        _emailSendMode = 'stopped';
        _emailStopIndex = d.importEmailSendProgress || 0;
      } else {
        _emailSendMode = 'idle'; _emailStopIndex = 0;
      }
      updateEmailSendBtn();

      // ── Restore Both send state ──
      if (bothStatus === 'running') {
        _bothSendMode = 'sending';
        _bothStopIndex = d.importBothSendProgress || 0;
        const bp = document.getElementById('import-both-progress');
        if (bp) bp.style.display = 'block';
        const logEl3 = document.getElementById('import-both-log');
        if (logEl3) logEl3.dataset.rendered = '0';
        startBothProgressPoll();
      } else if (bothStatus === 'stopped') {
        _bothSendMode = 'stopped';
        _bothStopIndex = d.importBothSendProgress || 0;
      } else {
        _bothSendMode = 'idle'; _bothStopIndex = 0;
      }
      updateBothSendBtn();

      refreshImportCreditDisplay();
    }
  });
}

// ── Validate email format ──
function isValidEmail(str) {
  if (!str) return false;
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(str).trim());
}

// ── Validate phone (at least 7 digits) ──
function isValidPhone(str) {
  if (!str) return false;
  return /\d{7,}/.test(String(str).replace(/[\s\-\+\(\)]/g,''));
}

// ── Auto-detect best column ──
function autoDetectCol(headers, keywords) {
  for (const kw of keywords) {
    const idx = headers.findIndex(h => h.toLowerCase().includes(kw.toLowerCase()));
    if (idx !== -1) return headers[idx];
  }
  return '';
}

function buildAutoMap(headers) {
  return {
    name:     autoDetectCol(headers, ['name','নাম','business','shop','company','title']),
    phone:    autoDetectCol(headers, ['phone','mobile','number','ফোন','contact','tel','cell']),
    email:    autoDetectCol(headers, ['email','mail','ইমেইল','e-mail']),
    whatsapp: autoDetectCol(headers, ['whatsapp','wa','wapp','wa_number']),
    website:  autoDetectCol(headers, ['website','web','url','site','link']),
    address:  autoDetectCol(headers, ['address','location','ঠিকানা','city','area']),
    rating:   autoDetectCol(headers, ['rating','rate','star','রেটিং']),
    category: autoDetectCol(headers, ['category','type','business_type','industry','বিভাগ']),
  };
}

// ── Parse CSV ──
function parseCSV(text) {
  const lines = text.trim().split(/\r?\n/);
  if (lines.length < 2) return { headers: [], rows: [] };
  const parseRow = line => {
    const cells = []; let cur = '', inQ = false;
    for (let i = 0; i < line.length; i++) {
      const c = line[i];
      if (c === '"') { inQ = !inQ; }
      else if (c === ',' && !inQ) { cells.push(cur.trim()); cur = ''; }
      else cur += c;
    }
    cells.push(cur.trim());
    return cells;
  };
  const headers = parseRow(lines[0]);
  const rows = lines.slice(1).map(l => parseRow(l)).filter(r => r.some(c => c));
  return { headers, rows };
}

// ── Parse XLSX ──
function parseXLSX(buffer) {
  try {
    const wb = XLSX.read(buffer, { type: 'array' });
    const ws = wb.Sheets[wb.SheetNames[0]];
    const json = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
    if (json.length < 2) return { headers: [], rows: [] };
    const headers = json[0].map(String);
    const rows = json.slice(1).filter(r => r.some(c => String(c).trim()));
    return { headers, rows };
  } catch(e) { return { headers: [], rows: [] }; }
}

// ── Render preview table ──
function renderImportPreview(headers, rows) {
  const previewRows = rows.slice(0, 5);
  let html = '<table><tr>' + headers.map(h => `<th>${h}</th>`).join('') + '</tr>';
  for (const row of previewRows) {
    html += '<tr>' + headers.map((_, i) => `<td>${row[i] !== undefined ? row[i] : ''}</td>`).join('') + '</tr>';
  }
  html += '</table>';
  const pt = document.getElementById('import-preview-table');
  const pc = document.getElementById('import-preview-count');
  if (pt) pt.innerHTML = html;
  if (pc) pc.textContent = rows.length + ' rows পাওয়া গেছে';
}

// ── Render column mapping dropdowns ──
function renderColMapping(headers, colMap) {
  const fields = [
    { key: 'name',     label: '👤 Name (নাম)' },
    { key: 'phone',    label: '📱 Phone (ফোন)' },
    { key: 'email',    label: '📧 Email' },
    { key: 'whatsapp', label: '💬 WhatsApp' },
    { key: 'website',  label: '🌐 Website' },
    { key: 'address',  label: '📍 Address' },
  ];
  const container = document.getElementById('import-col-mapping');
  if (!container) return;
  container.innerHTML = fields.map(f => `
    <div style="margin-bottom:4px">
      <div style="font-size:9px;color:#f97316;margin-bottom:2px;font-weight:600">${f.label}</div>
      <select class="import-map-select" data-field="${f.key}" style="background:#111;border:1px solid #272727;color:#e0e0e0;border-radius:7px;padding:6px 8px;font-size:10px;width:100%;outline:none;cursor:pointer">
        <option value="">— skip —</option>
        ${headers.map(h => `<option value="${h}" ${colMap[f.key]===h?'selected':''}>${h}</option>`).join('')}
      </select>
    </div>
  `).join('');
  container.querySelectorAll('.import-map-select').forEach(sel => {
    sel.addEventListener('change', () => { importColMap[sel.dataset.field] = sel.value; });
  });
}

// ── Rows → lead objects ──
function rowsToLeads(headers, rows, colMap) {
  const importType = document.querySelector('input[name="import-type"]:checked')?.value || 'whatsapp';
  const result = [];
  for (const row of rows) {
    const get = key => {
      const col = colMap[key];
      if (!col) return '';
      const idx = headers.indexOf(col);
      return idx !== -1 ? String(row[idx] || '').trim() : '';
    };
    const phone    = get('phone');
    const email    = get('email');
    const whatsapp = get('whatsapp') || phone;

    // Filter based on import type
    if (importType === 'whatsapp' && !isValidPhone(phone) && !isValidPhone(whatsapp)) continue;
    if (importType === 'email'    && !isValidEmail(email)) continue;
    if (importType === 'both'     && !isValidPhone(phone) && !isValidPhone(whatsapp) && !isValidEmail(email)) continue;

    result.push({
      name:      get('name')     || 'Unknown',
      phone:     isValidPhone(phone)    ? phone    : '—',
      email:     isValidEmail(email)    ? email    : '—',
      whatsapp:  isValidPhone(whatsapp) ? whatsapp : '—',
      website:   get('website')  || '—',
      address:   get('address')  || '—',
      rating:    get('rating')   || '—',
      category:  get('category') || '—',
      _imported: true,
    });
  }
  return result;
}

// ── Handle file ──
function handleImportFile(file) {
  if (!file) return;
  const ext = file.name.split('.').pop().toLowerCase();
  if (!['csv','xlsx','xls'].includes(ext)) {
    alert('❌ শুধুমাত্র .csv বা .xlsx ফাইল সাপোর্ট করে!');
    return;
  }
  importLog('');
  const dropZone = document.getElementById('import-drop-zone');
  if (dropZone) dropZone.innerHTML = '<div class="imp-drop-icon">⏳</div><div class="imp-drop-title" style="color:#fb923c">Processing...</div><div class="imp-drop-sub">' + file.name + '</div>';

  const reader = new FileReader();
  reader.onload = e => {
    try {
      let headers = [], rows = [];
      if (ext === 'csv') {
        ({ headers, rows } = parseCSV(e.target.result));
      } else {
        ({ headers, rows } = parseXLSX(new Uint8Array(e.target.result)));
      }
      if (!headers.length || !rows.length) {
        alert('❌ ফাইলে কোনো data পাওয়া যায়নি।');
        resetDropZone();
        return;
      }
      importHeaders = headers;
      importParsedRows = rows;
      importColMap = buildAutoMap(headers);

      renderImportPreview(headers, rows);
      renderColMapping(headers, importColMap);

      const previewSec = document.getElementById('import-preview-section');
      const actionBtns = document.getElementById('import-action-btns');
      const statsSec   = document.getElementById('import-stats-section');
      const sendSec    = document.getElementById('import-send-section');
      if (previewSec) previewSec.style.display = 'block';
      if (actionBtns) actionBtns.style.display = 'flex';
      if (statsSec)   statsSec.style.display   = 'none';
      if (sendSec)    sendSec.style.display     = 'none';

      if (dropZone) dropZone.innerHTML = '<div class="imp-drop-icon">✅</div><div class="imp-drop-title" style="color:#4ade80">' + file.name + '</div><div class="imp-drop-sub" style="color:#fb923c">' + rows.length + ' rows পাওয়া গেছে</div>';
    } catch(err) {
      alert('❌ ফাইল পড়তে সমস্যা হয়েছে: ' + err.message);
      resetDropZone();
    }
  };
  reader.onerror = () => { alert('❌ ফাইল পড়া যায়নি।'); resetDropZone(); };
  if (ext === 'csv') reader.readAsText(file, 'UTF-8');
  else reader.readAsArrayBuffer(file);
}

function resetDropZone() {
  const dz = document.getElementById('import-drop-zone');
  if (!dz) return;
  dz.innerHTML = '<div class="imp-drop-icon">📄</div><div class="imp-drop-title">CSV বা Excel ফাইল drag করুন এখানে</div><div class="imp-drop-sub">অথবা নিচের বাটন দিয়ে ফাইল বেছে নিন</div>';
  dz.style.borderColor = '';
  dz.style.background  = '';
}

// ── Confirm import ──
function confirmImport() {
  try {
    // Re-read column mapping from dropdowns
    document.querySelectorAll('#import-col-mapping .import-map-select').forEach(sel => {
      importColMap[sel.dataset.field] = sel.value;
    });

    // Parse rows into lead objects
    const allParsed = rowsToLeads(importHeaders, importParsedRows, importColMap);

    if (!allParsed.length) {
      alert('❌ কোনো valid lead পাওয়া যায়নি!\n\nPhone বা Email column mapping ঠিক করুন।');
      return;
    }

    // Deduplicate within the imported set (phone + email)
    const seenPhones = new Set();
    const seenEmails = new Set();
    const dedupedLeads = allParsed.filter(l => {
      if (l.phone !== '—' && seenPhones.has(l.phone)) return false;
      if (l.email !== '—' && seenEmails.has(l.email)) return false;
      if (l.phone !== '—') seenPhones.add(l.phone);
      if (l.email !== '—') seenEmails.add(l.email);
      return true;
    });
    const dupes = allParsed.length - dedupedLeads.length;

    // Store as separate importedLeads — NOT merged into scraped leads[]
    importedLeads = dedupedLeads;
    importStopIndex = 0;
    importSendMode = 'idle';
    saveImportedLeadsToStorage();

    const total    = importedLeads.length;
    const withPhone = importedLeads.filter(l => l.phone && l.phone !== '—').length;
    const withEmail = importedLeads.filter(l => l.email && l.email !== '—').length;

    // Update import success stats UI
    const statTotal = document.getElementById('import-stat-total');
    const statPhone = document.getElementById('import-stat-phone');
    const statEmail = document.getElementById('import-stat-email');
    const statDupe  = document.getElementById('import-stat-dupe');
    if (statTotal) statTotal.textContent = total;
    if (statPhone) statPhone.textContent = withPhone;
    if (statEmail) statEmail.textContent = withEmail;
    if (statDupe)  statDupe.textContent  = dupes > 0 ? '(' + dupes + ' duplicate skip হয়েছে)' : '';

    // Show stats + send sections, hide action buttons
    const statsSec  = document.getElementById('import-stats-section');
    const actionBtns= document.getElementById('import-action-btns');
    const sendSec   = document.getElementById('import-send-section');
    if (statsSec)   statsSec.style.display   = 'block';
    if (actionBtns) actionBtns.style.display = 'none';
    if (sendSec)    sendSec.style.display     = 'block';

    importLog('✅ ' + total + 'টি lead import হয়েছে! Phone: ' + withPhone + ' | Email: ' + withEmail + (dupes > 0 ? ' | Duplicate skip: ' + dupes : ''));
  } catch(err) {
    alert('❌ Import error: ' + err.message);
    console.error('Import error:', err);
  }
}

// ── Import log ──
function importLog(msg) {
  const el = document.getElementById('import-send-log');
  if (!el) return;
  if (!msg) { el.textContent = ''; return; }
  el.textContent += msg + '\n';
  el.scrollTop = el.scrollHeight;
}

