// IMPORT MARKETING — License + Credit Enforced
// ═══════════════════════════════════════════

let importSendStopped = false; // global stop flag

// ── Check license + credits before sending ──
async function checkImportReady(neededCount) {
  const data = await new Promise(r => chrome.storage.local.get(['licenseKey','creditsRemaining'], r));
  if (!data.licenseKey) {
    alert('❌ License Key নেই!\n\nAccount tab-এ গিয়ে License Key activate করুন।');
    return false;
  }
  const cr = typeof data.creditsRemaining === 'number' ? data.creditsRemaining : 0;
  if (cr <= 0) {
    alert('❌ Credits শেষ হয়ে গেছে! (0 credits)\n\nAccount tab-এ গিয়ে credits কিনুন।');
    return false;
  }
  if (cr < neededCount) {
    const ok = confirm(`⚠️ আপনার কাছে ${cr} credits আছে কিন্তু ${neededCount}টি lead পাঠাতে হবে।\n${cr}টি lead পাঠানোর পর auto-stop হবে।\n\nচালিয়ে যাবেন?`);
    if (!ok) return false;
  }
  return cr;
}

// ── Pretty log line ──
function importLogLine(idx, phone, name, status, note) {
  const el = document.getElementById('import-send-log');
  if (!el) return;
  const icons = { ok:'✅', fail:'❌', wait:'⏳', stop:'⏹', info:'💬' };
  const icon = icons[status] || '•';
  const display = name && name !== 'Unknown' ? name : phone;
  const noteHtml = note ? `<span class="imp-log-status-${status === 'ok' ? 'ok' : status === 'wait' ? 'wait' : 'fail'}">${note}</span>` : '';
  const line = document.createElement('div');
  line.className = 'imp-log-row';
  const statusClass = status === 'ok' ? 'ok' : status === 'wait' ? 'wait' : 'fail';
  const statusLabel = note || (status === 'ok' ? 'Sent' : status === 'wait' ? 'Wait' : 'Failed');
  line.innerHTML = `<span class="lr-icon">${icon}</span><span class="lr-idx">#${idx+1}</span><span class="lr-name">${display}</span><span class="lr-phone">${phone}</span><span class="lr-status ${statusClass}">${statusLabel}</span>`;
  el.appendChild(line);
  el.scrollTop = el.scrollHeight;
}

function importLogClear() {
  const el = document.getElementById('import-send-log');
  if (el) el.innerHTML = '';
}

function importLogInfo(msg) {
  const el = document.getElementById('import-send-log');
  if (!el) return;
  const line = document.createElement('div');
  line.className = 'imp-log-info-row';
  line.textContent = msg;
  el.appendChild(line);
  el.scrollTop = el.scrollHeight;
}

// ── Refresh credit display in send section ──
function refreshImportCreditDisplay() {
  chrome.storage.local.get(['creditsRemaining'], d => {
    const el = document.getElementById('import-credit-display');
    if (!el) return;
    const cr = typeof d.creditsRemaining === 'number' ? d.creditsRemaining : 0;
    el.textContent = cr + ' credits';
    el.style.color = cr <= 0 ? '#f87171' : cr <= 20 ? '#fbbf24' : '#fb923c';
  });
}

// ── Update WA send button based on importSendMode ──
function updateWaSendBtn() {
  const btn = document.getElementById('import-send-wa-btn');
  if (!btn) return;
  if (importSendMode === 'sending') {
    btn.innerHTML = '⏹ Stop Sending';
    btn.style.background = 'linear-gradient(135deg,#dc2626,#ef4444)';
    btn.disabled = false;
  } else if (importSendMode === 'stopped') {
    const remaining = importedLeads.length - importStopIndex;
    btn.innerHTML = `▶ Resume (${remaining} বাকি)`;
    btn.style.background = 'linear-gradient(135deg,#d97706,#f59e0b)';
    btn.disabled = false;
  } else {
    btn.innerHTML = '💬 WhatsApp পাঠান';
    btn.style.background = '';
    btn.disabled = false;
  }
}

// ── Stop button control (legacy, kept for email) ──
function setStopBtnVisible(visible) {
  const btn = document.getElementById('import-stop-btn');
  if (!btn) return;
  btn.style.display = visible ? 'flex' : 'none';
  if (!visible) { btn.disabled = false; btn.textContent = '⏹ STOP — Marketing বন্ধ করুন'; }
}

