// ── Refresh the Email master-switch banner in Import tab ──
function refreshEmailMasterStatus() {
  chrome.storage.local.get(['gmailAutoSend','gmailAccessToken','gmailSubject','gmailBody'], d => {
    const isOn = d.gmailAutoSend !== false;
    const hasToken = !!d.gmailAccessToken;
    const hasSubject = !!(d.gmailSubject && d.gmailSubject.trim());
    const hasBody = !!(d.gmailBody && d.gmailBody.trim());
    const banner = document.getElementById('import-email-master-status');
    const label  = document.getElementById('import-email-master-label');
    if (!banner) return;
    if (!hasToken) {
      banner.className = 'imp-wa-banner off';
      if (label) label.textContent = '📧 Email Auto-Send: Gmail connect নেই! Email tab থেকে Gmail connect করুন।';
    } else if (!isOn) {
      banner.className = 'imp-wa-banner off';
      if (label) label.textContent = '📧 Email Auto-Send: OFF 🔴 — Email tab থেকে ON করুন';
    } else if (!hasSubject || !hasBody) {
      banner.className = 'imp-wa-banner off';
      if (label) label.textContent = '📧 Email Auto-Send: Template নেই! Email tab থেকে Subject ও Body লিখুন।';
    } else {
      banner.className = 'imp-wa-banner on';
      if (label) label.textContent = '📧 Email Auto-Send: ON ✅ — Email পাঠানো যাবে';
    }
  });
}

