// Poll storage for live progress when popup is open
let _importProgressInterval = null;
function startImportProgressPoll() {
  if (_importProgressInterval) return;
  _importProgressInterval = setInterval(() => {
    refreshWaMasterStatus(); // always keep master switch status fresh
    refreshEmailMasterStatus(); // keep email master switch fresh too
    refreshWaTodayCount(); // keep WA today sent count fresh
    chrome.storage.local.get(['importSendStatus','importSendProgress','importSendTotal','importSendLog','creditsRemaining'], d => {
      const status   = d.importSendStatus || 'idle';
      const progress = d.importSendProgress || 0;
      const total    = d.importSendTotal    || importedLeads.length;
      const log      = d.importSendLog      || [];

      // Update progress bar
      const progSec  = document.getElementById('import-send-progress');
      const progText = document.getElementById('import-progress-text');
      const progBar  = document.getElementById('import-progress-bar');
      if (progSec && total > 0) {
        progSec.style.display = 'block';
        if (progText) progText.textContent = `${progress} / ${total}`;
        if (progBar)  progBar.style.width  = Math.round((progress/total)*100) + '%';
      }

      // Sync credits display
      if (typeof d.creditsRemaining === 'number') {
        updateHeaderCredits(d.creditsRemaining);
        refreshImportCreditDisplay();
      }

      // Render new log entries
      const logEl = document.getElementById('import-send-log');
      if (logEl && log.length > 0) {
        const rendered = parseInt(logEl.dataset.rendered || '0');
        if (log.length > rendered) {
          const newEntries = log.slice(rendered);
          newEntries.forEach(entry => {
            const line = document.createElement('div');
            line.style.cssText = 'padding:1px 0;font-size:10px;border-bottom:1px solid #1a1a1a';
            if (entry.type === 'ok')    line.style.color = '#4ade80';
            else if (entry.type === 'fail')  line.style.color = '#f87171';
            else if (entry.type === 'wait')  line.style.color = '#fbbf24';
            else if (entry.type === 'stop')  line.style.color = '#f97316';
            else if (entry.type === 'done')  line.style.color = '#22d3ee';
            else if (entry.type === 'error') line.style.color = '#ef4444';
            else line.style.color = '#aaa';
            const nameStr = entry.name ? ` [${entry.name}]` : '';
            const phoneStr = entry.phone ? ` ${entry.phone}` : '';
            line.textContent = `#${(entry.idx||0)+1}${nameStr}${phoneStr} — ${entry.msg || entry.type}`;
            if (entry.type === 'done' || entry.type === 'stop' || entry.type === 'error') {
              line.textContent = entry.msg;
            }
            logEl.appendChild(line);
            logEl.scrollTop = logEl.scrollHeight;
          });
          logEl.dataset.rendered = String(log.length);
        }
      }

      // Update button state based on background status
      if (status === 'running') {
        importSendMode = 'sending';
        updateWaSendBtn();
      } else if (status === 'stopped') {
        importSendMode = 'stopped';
        importStopIndex = d.importSendProgress || 0;
        chrome.storage.local.set({ importStopIndex: importStopIndex });
        updateWaSendBtn();
        stopImportProgressPoll();
        const sendEmailBtn = document.getElementById('import-send-email-btn');
        if (sendEmailBtn) sendEmailBtn.disabled = false;
        updateBothSendBtn();
      } else if (status === 'done') {
        importSendMode = 'idle';
        importStopIndex = 0;
        chrome.storage.local.set({ importStopIndex: 0 });
        updateWaSendBtn();
        stopImportProgressPoll();
        const sendEmailBtn = document.getElementById('import-send-email-btn');
        if (sendEmailBtn) sendEmailBtn.disabled = false;
        updateBothSendBtn();
      }
    });
  }, 800);
}

function stopImportProgressPoll() {
  if (_importProgressInterval) {
    clearInterval(_importProgressInterval);
    _importProgressInterval = null;
  }
}

async function sendWaToImported() {
  // ── If currently SENDING → STOP ──
  if (importSendMode === 'sending') {
    chrome.runtime.sendMessage({ action: 'stopImportSend' });
    const btn = document.getElementById('import-send-wa-btn');
    if (btn) { btn.innerHTML = '⏳ Stopping...'; btn.disabled = true; }
    return;
  }

  try {
    const phonLeads = importedLeads.map(l => {
      if (!isValidPhone(l.phone) && isValidPhone(l.whatsapp)) return {...l, phone: l.whatsapp};
      return l;
    }).filter(l => isValidPhone(l.phone));

    if (!phonLeads.length) { alert('❌ Import করা leads-এ কোনো valid phone নম্বর নেই।'); return; }
    if (!waConnected || !waToken) { alert('❌ WhatsApp connect নেই!\n\nWhatsApp tab-এ গিয়ে QR scan করুন।'); return; }

    // ── Master switch check: WhatsApp ON/OFF ──
    const waStateCheck = await new Promise(r => chrome.storage.local.get(['waAutoSend'], r));
    if (waStateCheck.waAutoSend === false) {
      alert('❌ WhatsApp Auto-Send বন্ধ আছে!\n\nWhatsApp tab-এ গিয়ে ON করুন, তারপর আবার চেষ্টা করুন।');
      importSendMode = 'idle';
      updateWaSendBtn();
      return;
    }

    // ── Always reload delay from storage ──
    const delayData = await new Promise(r => chrome.storage.local.get(['waDelaySec','waDelayVal','waDelayUnit'], r));
    if (delayData.waDelaySec !== undefined) waSendDelaySec = delayData.waDelaySec;

    // ── Load template ──
    const stored = await new Promise(r => chrome.storage.local.get(['whatsappSms','waMsgTemplate'], r));
    waMsgTemplate = stored.whatsappSms || stored.waMsgTemplate || waMsgTemplate || '';
    if (!waMsgTemplate) { alert('❌ WhatsApp message template নেই!\n\nWhatsApp tab-এ গিয়ে template লিখুন।'); return; }

    // ── License key ──
    const licData = await new Promise(r => chrome.storage.local.get(['licenseKey'], r));
    if (!licData.licenseKey) { alert('❌ License key নেই!'); return; }

    // ── Credit check ──
    const availableCredits = await checkImportReady(phonLeads.length);
    if (!availableCredits) return;

    // ── Set UI to sending ──
    importSendMode = 'sending';
    updateWaSendBtn();
    const sendEmailBtn = document.getElementById('import-send-email-btn');
    if (sendEmailBtn) sendEmailBtn.disabled = true;

    // ── Clear log if starting fresh ──
    const startFrom = importStopIndex;
    if (startFrom === 0) {
      importLogClear();
      const logEl = document.getElementById('import-send-log');
      if (logEl) logEl.dataset.rendered = '0';
      chrome.storage.local.set({ importSendLog: [], importSendProgress: 0 });
    } else {
      // resuming — keep rendered count in sync
      const logEl = document.getElementById('import-send-log');
      // re-render nothing, background will append new entries
    }

    // ── Show progress section ──
    const progSec = document.getElementById('import-send-progress');
    if (progSec) progSec.style.display = 'block';
    importLogInfo(`🚀 WhatsApp sending ${startFrom > 0 ? 'resume' : 'শুরু'} — ${phonLeads.length - startFrom}টি বাকি — Background এ চলবে`);

    // ── Delegate to background service worker ──
    chrome.runtime.sendMessage({
      action: 'startImportSend',
      data: {
        leads:     phonLeads,
        template:  waMsgTemplate,
        token:     waToken,
        delaySec:  waSendDelaySec,
        licenseKey: licData.licenseKey,
        startFrom: startFrom
      }
    });

    // ── Start polling for progress ──
    startImportProgressPoll();

  } catch(err) {
    console.error('sendWaToImported error:', err);
    importLogInfo('❌ Error: ' + err.message);
    importSendMode = 'idle';
    updateWaSendBtn();
  }
}

// ══════════════════════════════════
// Send Email to imported leads — with Stop/Resume & master switch check
// ══════════════════════════════════
let _emailSendMode = 'idle'; // 'idle' | 'sending' | 'stopped'
let _emailStopRequested = false;
let _emailStopIndex = 0;

function updateEmailSendBtn() {
  const btn = document.getElementById('import-send-email-btn');
  if (!btn) return;
  if (_emailSendMode === 'sending') {
    btn.innerHTML = '⏹ Stop Email';
    btn.style.background = 'linear-gradient(135deg,#6d28d9,#7c3aed)';
    btn.disabled = false;
  } else if (_emailSendMode === 'stopped') {
    const emailLeads = importedLeads.filter(l => isValidEmail(l.email));
    const remaining  = emailLeads.length - _emailStopIndex;
    btn.innerHTML = `▶ Resume Email (${remaining} বাকি)`;
    btn.style.background = 'linear-gradient(135deg,#5b21b6,#6d28d9)';
    btn.disabled = false;
  } else {
    btn.innerHTML = '📧 Email পাঠান';
    btn.style.background = '';
    btn.disabled = false;
  }
}

async function sendEmailToImported() {
  // If currently sending → STOP (delegate to background)
  if (_emailSendMode === 'sending') {
    chrome.runtime.sendMessage({ action: 'stopImportEmailSend' });
    _emailSendMode = 'stopped';
    const btn = document.getElementById('import-send-email-btn');
    if (btn) { btn.innerHTML = '⏳ Stopping...'; btn.disabled = true; }
    stopEmailProgressPoll();
    setTimeout(() => { updateEmailSendBtn(); }, 600);
    return;
  }

  try {
    const emailLeads = importedLeads.filter(l => isValidEmail(l.email));
    if (!emailLeads.length) { alert('❌ Import করা leads-এ কোনো valid email নেই।'); return; }

    const licData = await new Promise(r => chrome.storage.local.get(['licenseKey'], r));
    if (!licData.licenseKey) { alert('❌ License Key নেই!\n\nAccount tab-এ License Key activate করুন।'); return; }

    const data = await new Promise(r => chrome.storage.local.get(
      ['gmailAccessToken','gmailSubject','gmailBody','emailDelaySec','gmailAutoSend'], r
    ));
    if (!data.gmailAccessToken)    { alert('❌ Gmail connect নেই!\n\nEmail tab-এ Gmail connect করুন।'); return; }
    if (data.gmailAutoSend === false) { alert('❌ Email Auto-Send বন্ধ!\n\nEmail tab-এ ON করুন।'); return; }

    const subject = (data.gmailSubject || '').trim();
    const body    = (data.gmailBody    || '').trim();
    if (!subject) { alert('❌ Email Subject নেই!\n\nEmail tab-এ Subject লিখুন।'); return; }
    if (!body)    { alert('❌ Email Body নেই!\n\nEmail tab-এ Body লিখুন।'); return; }

    const credData = await new Promise(r => chrome.storage.local.get(['creditsRemaining'], r));
    if ((credData.creditsRemaining || 0) <= 0) { alert('❌ Credits নেই!'); return; }

    const delaySec  = parseInt(data.emailDelaySec) || 5;
    const startFrom = _emailSendMode === 'stopped' ? _emailStopIndex : 0;

    _emailSendMode = 'sending';
    _emailStopRequested = false;
    updateEmailSendBtn();

    const ep = document.getElementById('import-email-progress');
    if (ep) ep.style.display = 'block';
    if (startFrom === 0) {
      chrome.storage.local.set({ importEmailSendLog: [], importEmailSendProgress: 0 });
      const logEl = document.getElementById('import-email-log');
      if (logEl) { logEl.innerHTML = ''; logEl.dataset.rendered = '0'; }
    }

    const sendWaBtn = document.getElementById('import-send-wa-btn');
    if (sendWaBtn) sendWaBtn.disabled = true;

    // Delegate to background service worker — runs even when popup closed
    chrome.runtime.sendMessage({
      action: 'startImportEmailSend',
      data: {
        leads:      emailLeads,
        subject,
        body,
        delaySec,
        licenseKey: licData.licenseKey,
        startFrom
      }
    });
    startEmailProgressPoll();

  } catch(err) {
    console.error('sendEmailToImported error:', err);
    _emailSendMode = 'idle';
    updateEmailSendBtn();
  }
}

// ── Import type toggle UI ──
function updateImportTypeUI() {
  const val = document.querySelector('input[name=\"import-type\"]:checked')?.value || 'whatsapp';
  const waLabel    = document.getElementById('import-type-wa-label');
  const emailLabel = document.getElementById('import-type-email-label');
  const bothLabel  = document.getElementById('import-type-both-label');
  if (waLabel)    waLabel.className    = 'imp-type-card inactive';
  if (emailLabel) emailLabel.className = 'imp-type-card inactive';
  if (bothLabel)  bothLabel.className  = 'imp-type-card inactive';
  if (val === 'whatsapp' && waLabel)    waLabel.className    = 'imp-type-card active-wa';
  if (val === 'email'    && emailLabel) emailLabel.className = 'imp-type-card active-email';
  if (val === 'both'     && bothLabel)  bothLabel.className  = 'imp-type-card active-both';
  // Persist selection
  chrome.storage.local.set({ importLeadType: val });
}

// ── Both send mode state ──
let _bothSendMode = 'idle'; // 'idle' | 'sending' | 'stopped'
let _bothStopIndex = 0;
